1	// Fringe Planner — page logic.
2	//
3	// An ES module: shares no *globals* with the home site's js/app.js, but does
4	// share real code with it — anything both pages must agree on is imported from
5	// ../shared/, not copy-pasted. Wires the pure computation engine (./lib/*.js)
6	// to the UI.
7	//
8	// The page has one state switch, keyed on whether a favourites set is in:
9	// without one, the intake panel (drag/drop or pick a favourites CSV, or load
10	// the bundled sample) is all there is; with one, the availability calendar +
11	// the instant plan replace it. There is no "Plan" button — the itinerary
12	// recomputes live whenever the date window or any control changes.
13	
14	import { isInUK } from "../shared/geo.js";
15	import { parseFavourites, urlFromSlug } from "./lib/favourites.js";
16	import { buildIndex, matchFavourites, summarize, buildSchedule, placementDiagnostics, slotKey } from "./lib/engine.js";
17	import { isAvailable } from "./lib/availability.js";
18	import { toCsv, toIcs, slotEndTime } from "./lib/itinerary.js";
19	import { distanceKm, travelMinutes } from "./lib/travel.js";
20	import { rehydrateShows } from "./lib/hydrate.js";
21	
22	// ES modules are always strict mode, so no "use strict" directive is needed.
23	
24	// --- Constants --------------------------------------------------------
25	
26	const DATA_URL = "../data/normalized/shows.min.json"; // compact catalogue; rehydrated against VENUES_URL
27	const VENUES_URL = "../data/venues.json"; // shared lookups (enums + venue map) the catalogue indexes into
28	const APP_VERSION_URL = "../package.json"; // single source of truth for the version in the perf pill
29	
30	const YEAR = 2026;
31	const MONTH = "08"; // August, 2-digit
32	const DAYS_IN_MONTH = 31; // Aug 1–31 is the axis this calendar draws.
33	const FEST_START_DAY = 7; // The Fringe runs Fri 7 – Sun 31 Aug 2026; days 1–6 draw as a shaded "before it opens" zone.
34	
35	const T_MIN = 0; // 00:00 — the calendar's catchable-count filter never narrows on start time.
36	const T_MAX = 1440; // 24:00
37	
38	const DEFAULT_D0 = 7; // default date window: Aug 7 → Aug 24 (the festival trip window)
39	const DEFAULT_D1 = 24;
40	
41	// The schedule axis, and the range a "day ends" can reach: a Fringe evening
42	// runs past midnight, so the day is drawn from 09:00 to 27:00 (03:00) and a show
43	// may be allowed to finish any time up to that late edge.
44	const AXIS_TOP_MIN = 9 * 60; // 09:00 — top of every day column
45	const AXIS_BOTTOM_MIN = 27 * 60; // 27:00 = 03:00 — bottom of every day column
46	const DAY_END_CEIL = AXIS_BOTTOM_MIN; // a "day ends" can be set as late as 27:00
47	
48	// Default day-hours window (minutes of day). The day ends at 25:00 (01:00) by
49	// default so ordinary late-night shows are catchable out of the box.
50	const DEFAULT_DAY_START = 9 * 60; // 09:00
51	const DEFAULT_DAY_END = 25 * 60; // 25:00 = 01:00
52	
53	const STORAGE_KEY = "edfringe.plan.favourites.v1";
54	const TTL_MS = 3 * 24 * 60 * 60 * 1000; // keep for 3 days, then forget
55	
56	// Genre → a small emoji drawn on the left of each scheduled block. Keys are the
57	// ten headline genres in shows.json; anything else falls back to a ticket.
58	const GENRE_EMOJI = {
59	  "Comedy": "😂",
60	  "Theatre": "🎭",
61	  "Cabaret and Variety": "🎪",
62	  "Children's Shows": "🧸",
63	  "Dance, Physical Theatre & Circus": "💃",
64	  "Events": "✨",
65	  "Exhibitions": "🖼️",
66	  "Music": "🎵",
67	  "Musicals and Opera": "🎶",
68	  "Spoken Word": "🗣️",
69	};
70	function genreEmoji(genre) {
71	  return GENRE_EMOJI[genre] || "🎟️";
72	}
73	
74	// Travel modes: emoji + a verb for the leg label ("12 min walk" / "by bike").
75	const MODE_META = {
76	  walk: { emoji: "🚶", verb: "walk" },
77	  bike: { emoji: "🚲", verb: "by bike" },
78	  car: { emoji: "🚗", verb: "by car" },
79	};
80	
81	// --- Small helpers ------------------------------------------------------
82	
83	const $ = (id) => document.getElementById(id);
84	const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
85	const pad2 = (n) => String(n).padStart(2, "0");
86	
87	/** "YYYY-MM-DD" for a day-of-month within August 2026. */
88	function dateStr(day) {
89	  return `${YEAR}-${MONTH}-${pad2(day)}`;
90	}
91	
92	/** "HH:MM" for a minute-of-day (caps at 23:59 for the 1440 sentinel). */
93	function minToHHMM(min) {
94	  const m = Math.min(1439, Math.max(0, Math.round(min)));
95	  return `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`;
96	}
97	/**
98	 * Extended-hours clock for a minute-of-day that may run past midnight: 1500 →
99	 * "25:00", 1470 → "24:30". Used for the "day ends" control and the after-hours
100	 * lines/labels on the 09:00–27:00 schedule axis.
101	 */
102	function minToDayClock(min) {
103	  const m = Math.max(0, Math.round(min));
104	  return `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`;
105	}
106	/** Parse an "HH:MM" time-input value to minutes of day (null if blank). */
107	function hhmmToMin(str) {
108	  if (!str) return null;
109	  const [h, m] = str.split(":").map(Number);
110	  if (Number.isNaN(h) || Number.isNaN(m)) return null;
111	  return h * 60 + m;
112	}
113	
114	// 1 Aug 2026 is a Saturday; compute weekday letters from real dates.
115	const DOW_SHORT = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
116	function dow(day) {
117	  return new Date(Date.UTC(YEAR, 7, day)).getUTCDay();
118	}
119	function dowShort(day) {
120	  return DOW_SHORT[dow(day)];
121	}
122	function isWeekend(day) {
123	  const d = dow(day);
124	  return d === 0 || d === 6;
125	}
126	
127	// --- App state ------------------------------------------------------------
128	
129	const state = {
130	  index: null, // Map<slug, show> — the full catalogue
131	  venueCoords: null, // { [venueCode]: {lat, lng} }
132	  // The working favourites, as slugs — the single source of truth for what's on
133	  // the grid and what we persist. Mutated by add (DEBUG) / remove-a-row, so the
134	  // stored list always mirrors the shows on screen, not the original upload.
135	  favSlugs: [],
136	  matched: [], // full show objects for the user's matched favourites
137	  totalFavourites: 0,
138	  missingSlugs: [],
139	  filename: "",
140	  savedAt: null,
141	  pendingUpload: null,
142	  // Date window (drives summarize()'s filter):
143	  d0: DEFAULT_D0,
144	  d1: DEFAULT_D1,
145	  // Day-hours + meal breaks + travel mode + must-sees (drive buildSchedule):
146	  dayStartMin: DEFAULT_DAY_START,
147	  dayEndMin: DEFAULT_DAY_END,
148	  mealBreaks: [
149	    { id: "lunch", enabled: true, startMin: 12 * 60 + 30, endMin: 13 * 60 + 30 },
150	    { id: "dinner", enabled: false, startMin: 18 * 60, endMin: 19 * 60 },
151	  ],
152	  // "Getting there" / "getting out" blocks (minute-of-day), applied to the first
153	  // (arrival) and last (departure) day of the trip window. Like meal breaks but
154	  // date-specific — the dates are derived from d0/d1 at plan time. Drag the block
155	  // edge on the schedule to set how much of the day travel eats.
156	  arrival: { endMin: 11 * 60, enabled: true },      // no shows before this on day one
157	  departure: { startMin: 22 * 60, enabled: true },  // no shows after this on the last day
158	  mode: "walk",
159	  // Must-sees, keyed by slug. Value `true` = pin the show (the scheduler picks a
160	  // performance); a slotKey string = pin that one specific performance. Click a
161	  // show name to toggle the first, click a performance mark to toggle the second.
162	  forced: new Map(),
163	  // Populated once per upload by buildCalendar():
164	  laneRefs: [], // [{ slug, el, statusEl }] in display (sorted) order
165	  layout: { trackLeft: 0, trackWidth: 0, dayW: 0 },
166	  dayHeaderBuilt: false,
167	  // The latest plan.
168	  schedule: null,
169	  scheduledSlugs: new Set(),
170	  // slug -> slotKey of the one performance the plan actually set for that show,
171	  // so the grid can ring the chosen day/time (not just flag the whole lane).
172	  selectedSlot: new Map(),
173	  diag: null, // latest placementDiagnostics(): which controls block which shows
174	  schedAxis: null, // { axisTopMin, axisBottomMin, hourPx, headPx } for overlay dragging
175	  // Build version + reschedule-timing telemetry (surfaced in the header pill).
176	  version: null,
177	  perf: { count: 0, sum: 0, last: 0, min: Infinity, max: 0 },
178	};
179	
180	// --- Data loading + rehydration ---------------------------------------
181	//
182	// The planner downloads two files: the compact catalogue (shows.min.json, packed
183	// by scraper/normalize.py) and the shared lookups (venues.json). rehydrateShows()
184	// (./lib/hydrate.js) unpacks the first against the second back into the full
185	// records the engine expects — every enum is an index into a venues.json list,
186	// venueName is rebuilt from the venue code + room, dates are MMDD ints, and the
187	// bare image GUID gets its host prefix re-attached — so the rest of the app sees
188	// a ready-to-use catalogue identical in shape to the old shows.json.
189	
190	let dataPromise = null;
191	
192	function loadData() {
193	  dataPromise = (async () => {
194	    // Both files are required to rehydrate: the compact catalogue and the lookups
195	    // it indexes into. Fetch them together.
196	    const [wire, lookups] = await Promise.all([
197	      fetchJson(DATA_URL),
198	      fetchJson(VENUES_URL),
199	    ]);
200	    state.venueCoords = lookups.venues || null; // venue map drives travel legs/gaps
201	    state.index = buildIndex(rehydrateShows(wire, lookups, YEAR));
202	    restoreStoredFavourites();
203	    return state.index;
204	  })();
205	  dataPromise.catch(() => {});
206	  return dataPromise;
207	}
208	
209	async function fetchJson(url) {
210	  const res = await fetch(url);
211	  if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
212	  return res.json();
213	}
214	
215	async function ensureData() {
216	  if (state.index) return state.index;
217	  if (!dataPromise) loadData();
218	  $("errorState").hidden = true;
219	  $("loadingState").hidden = false;
220	  try {
221	    return await dataPromise;
222	  } catch (err) {
223	    dataPromise = null;
224	    throw err;
225	  } finally {
226	    $("loadingState").hidden = true;
227	  }
228	}
229	
230	// --- Local persistence (localStorage, 3-day TTL) --------------------------
231	
232	function saveFavourites(slugs, filename, savedAt) {
233	  try {
234	    localStorage.setItem(STORAGE_KEY, JSON.stringify({ v: 1, slugs, filename, savedAt }));
235	  } catch (err) {
236	    console.warn("Fringe Planner: couldn't save favourites locally", err);
237	  }
238	}
239	
240	function loadStoredFavourites() {
241	  let raw = null;
242	  try {
243	    raw = localStorage.getItem(STORAGE_KEY);
244	  } catch (err) {
245	    console.warn("Fringe Planner: local storage unavailable", err);
246	    return null;
247	  }
248	  if (!raw) return null;
249	  let data;
250	  try {
251	    data = JSON.parse(raw);
252	  } catch {
253	    clearStoredFavourites();
254	    return null;
255	  }
256	  if (!data || !Array.isArray(data.slugs) || typeof data.savedAt !== "number") {
257	    clearStoredFavourites();
258	    return null;
259	  }
260	  if (Date.now() - data.savedAt > TTL_MS) {
261	    clearStoredFavourites();
262	    return null;
263	  }
264	  return {
265	    slugs: data.slugs.filter((s) => typeof s === "string"),
266	    filename: typeof data.filename === "string" ? data.filename : "",
267	    savedAt: data.savedAt,
268	  };
269	}
270	
271	function clearStoredFavourites() {
272	  try {
273	    localStorage.removeItem(STORAGE_KEY);
274	  } catch (err) {
275	    console.warn("Fringe Planner: couldn't clear stored favourites", err);
276	  }
277	}
278	
279	function restoreStoredFavourites() {
280	  const data = loadStoredFavourites();
281	  if (!data || data.slugs.length === 0) return;
282	  applyFavourites(data.slugs, data.filename, data.savedAt, { scroll: false });
283	}
284	
285	function clearFavourites() {
286	  clearStoredFavourites();
287	  state.favSlugs = [];
288	  state.totalFavourites = 0;
289	  state.matched = [];
290	  state.missingSlugs = [];
291	  state.filename = "";
292	  state.savedAt = null;
293	  state.forced = new Map();
294	
295	  const summaryEl = $("uploadSummary");
296	  summaryEl.hidden = true;
297	  summaryEl.classList.remove("is-partial");
298	  $("missingList").hidden = true;
299	  $("missingList").innerHTML = "";
300	  $("screen2").hidden = true;
301	  $("screen3").hidden = true;
302	  state.schedule = null;
303	  state.scheduledSlugs = new Set();
304	  const pageHead = $("pageHead");
305	  if (pageHead) pageHead.hidden = false; // bring the intro back on the empty state
306	  $("screen1").hidden = false;
307	  $("screen1").scrollIntoView({ behavior: "smooth", block: "start" });
308	}
309	
310	// --- Screen 1: favourites intake -----------------------------------------
311	
312	function handleFile(file) {
313	  if (!file) return;
314	  const reader = new FileReader();
315	  reader.onload = () => processFavouritesText(String(reader.result || ""), file.name);
316	  reader.onerror = () => {
317	    console.error("Fringe Planner: failed to read file", reader.error);
318	    alert("Couldn't read that file — please try again.");
319	  };
320	  reader.readAsText(file);
321	}
322	
323	function processFavouritesText(text, filename) {
324	  const slugs = parseFavourites(text);
325	  const savedAt = Date.now();
326	  if (slugs.length > 0) saveFavourites(slugs, filename, savedAt);
327	  applyFavourites(slugs, filename, savedAt, { scroll: true });
328	}
329	
330	async function applyFavourites(slugs, filename, savedAt, { scroll = false, keepForced = false } = {}) {
331	  state.pendingUpload = { slugs, filename, savedAt, scroll };
332	
333	  let index;
334	  try {
335	    index = await ensureData();
336	  } catch (err) {
337	    console.error("Fringe Planner: failed to load show data", err);
338	    $("errorDetail").textContent =
339	      "Check your connection and try again. (" + (err && err.message ? err.message : "unknown error") + ")";
340	    $("errorState").hidden = false;
341	    return;
342	  }
343	
344	  const { matched, missingSlugs } = matchFavourites(slugs, index);
345	  state.pendingUpload = null;
346	
347	  state.favSlugs = slugs.slice();
348	  state.totalFavourites = slugs.length;
349	  state.matched = matched;
350	  state.missingSlugs = missingSlugs;
351	  state.filename = filename;
352	  state.savedAt = savedAt;
353	  // A fresh upload clears must-sees; an add/remove keeps the pins still on the grid.
354	  const survivingSlugs = new Set(matched.map((s) => s.slug));
355	  state.forced = keepForced
356	    ? new Map([...state.forced].filter(([slug]) => survivingSlugs.has(slug)))
357	    : new Map();
358	
359	  if (matched.length > 0) {
360	    state.d0 = DEFAULT_D0;
361	    state.d1 = DEFAULT_D1;
362	    renderFavLine();
363	    buildCalendar(); // builds the lanes DOM…
364	    refresh(); // …then the first plan + verdicts + hero
365	    $("screen1").hidden = true;
366	    showCalendar({ scroll });
367	  } else {
368	    renderUploadSummary();
369	    $("screen1").hidden = false;
370	    $("screen2").hidden = true;
371	  }
372	}
373	
374	function dayDiff(a, b) {
375	  const da = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate());
376	  const db = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate());
377	  return Math.round((db - da) / 86400000);
378	}
379	
380	function fmtSavedWhen(ts) {
381	  if (!ts) return "this session";
382	  const then = new Date(ts);
383	  const days = dayDiff(then, new Date());
384	  if (days <= 0) return "today";
385	  if (days === 1) return "yesterday";
