  updateBlockLabels(state.diag);

  const bySlug = new Map(summ.shows.map((s) => [s.slug, s]));
  applyVerdicts(bySlug, filter);
  updateHero(summ.counts, schedule.counts);
  updatePlanWindowLabel();

