1948	/** A stable 0..1 pseudo-random from three integers (cell x, cell y, salt). */
1949	function decorHash(x, y, salt) {
1950	  let h = (Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(salt, 83492791)) >>> 0;
1951	  h ^= h >>> 13;
1952	  h = Math.imul(h, 0x5bd1e995) >>> 0;
1953	  h ^= h >>> 15;
1954	  return (h >>> 0) / 4294967296;
1955	}
