1964	function buildDecorHTML(w, h, setName, seed) {
1965	  const set = DECOR_SETS[setName] || DECOR_SETS.food;
1966	  const salt = decorSalt(`${seed}:${setName}`);
1967	  const cols = Math.max(1, Math.ceil(w / DECOR_CELL_PX));
1968	  const rows = Math.max(1, Math.ceil(h / DECOR_CELL_PX));
1969	  let html = "";
1970	  for (let j = 0; j < rows; j++) {
1971	    for (let i = 0; i < cols; i++) {
1972	      const jx = (decorHash(i, j, salt + 1) - 0.5) * DECOR_CELL_PX * 0.8;
1973	      const jy = (decorHash(i, j, salt + 2) - 0.5) * DECOR_CELL_PX * 0.8;
1974	      const cx = i * DECOR_CELL_PX + DECOR_CELL_PX / 2 + jx;
1975	      const cy = j * DECOR_CELL_PX + DECOR_CELL_PX / 2 + jy;
1976	      if (cx < 0 || cx > w || cy < 0 || cy > h) continue;
1977	      const emoji = set[Math.floor(decorHash(i, j, salt + 3) * set.length)];
1978	      const size = (11 + decorHash(i, j, salt + 4) * 13).toFixed(1);
1979	      const rot = Math.round(decorHash(i, j, salt + 5) * 80 - 40);
1980	      const op = (0.55 + decorHash(i, j, salt + 6) * 0.45).toFixed(2);
1981	      html += `<span style="left:${cx.toFixed(1)}px;top:${cy.toFixed(1)}px;font-size:${size}px;opacity:${op};transform:translate(-50%,-50%) rotate(${rot}deg)">${emoji}</span>`;
1982	    }
1983	  }
1984	  return html;
1985	}
