1	/* Fringe Planner — stylesheet
2	 * Extracted/adapted from plan/design/mock.html. Brand tokens match the home
3	 * site's css/styles.css (violet #6c4cf1, ink/muted/hairline, 16px radius,
4	 * soft shadow, Plus Jakarta Sans display + Inter body).
5	 * The container is wider than the home site's 1120px: the planner's payload is
6	 * two dense grids (a 31-day availability calendar and a multi-week schedule),
7	 * which were being squeezed into a narrow strip with big empty margins on wide
8	 * screens — so this page gets more room, while the prose blocks inside stay
9	 * capped at a readable width.
10	 * This stylesheet is self-contained — the planner does not load styles.css.
11	 */
12	
13	:root {
14	  --violet: #6c4cf1;
15	  --violet-dark: #5a3fd6;
16	  --ink: #101828;
17	  --paper: #ffffff;
18	  --bg: #f7f8fa;
19	  --muted: #667085;
20	  --line: #eaecf0;
21	  --ok: #059669;
22	  --ok-text: #047857;
23	  --ok-bg: #e6f7ee;
24	  --warn: #ef4444;
25	  /* Performance-date availability palette — taken from edfringe.com's own
26	     ticket day-picker legend so the calendar reads the same as the official
27	     site. Violet stays reserved for the date-window instrument + chrome. */
28	  --fr-avail: #2ac9de;    /* tickets available */
29	  --fr-2for1: #ffce00;    /* 2-for-1 (solid fallback, e.g. the thin schedule accent) */
30	  /* 2-for-1 reads as its two halves — available + free — interlaced on the
31	     diagonal, so the mark says "a bit of both" without a new colour. */
32	  --fr-2for1-weave: repeating-linear-gradient(45deg, var(--fr-avail) 0 3px, var(--fr-free) 3px 6px);
33	  --fr-preview: #3438ff;  /* preview show */
34	  --fr-free: #00bf57;     /* free (ticketed / non-ticketed) */
35	  --fr-event: #8c4fd9;    /* event-specific */
36	  --fr-noalloc: #ef3934;  /* no allocation — contact venue */
37	  --fr-sold-bg: #e6e9ef;  /* sold out — greyed, as the official picker disables it */
38	  --fr-sold-line: #c6cdda;
39	  --fr-locked: linear-gradient(120deg, #fdf3c4 0%, #f3d269 45%, #eac247 100%); /* locked-in day mark — a gold bar */
40	  --fr-ink: #00243d;      /* edfringe.com ink */
41	  --shadow-soft: 0 12px 30px rgba(16, 24, 40, 0.08);
42	  --maxw: 1400px;
43	  --radius: 16px;
44	  --sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
45	  --display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
46	  /* A small violet padlock, used as the cursor on every "click to lock into the
47	     plan" target (show names, day marks, scheduled blocks) so the affordance is
48	     shown, not spelled out. Falls back to the pointer where SVG cursors aren't
49	     honoured. */
50	  --lock-cursor:
51	    url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20width='28'%20height='28'%20viewBox='0%200%2024%2024'%3E%3Cpath%20d='M8%2010.5V7.5a4%204%200%200%201%208%200v3'%20fill='none'%20stroke='%23ffffff'%20stroke-width='3.6'%20stroke-linecap='round'/%3E%3Cpath%20d='M8%2010.5V7.5a4%204%200%200%201%208%200v3'%20fill='none'%20stroke='%236c4cf1'%20stroke-width='2'%20stroke-linecap='round'/%3E%3Crect%20x='4.6'%20y='10.5'%20width='14.8'%20height='10.5'%20rx='2.6'%20fill='%236c4cf1'%20stroke='%23ffffff'%20stroke-width='1.4'/%3E%3Ccircle%20cx='12'%20cy='15'%20r='1.5'%20fill='%23ffffff'/%3E%3Crect%20x='11.25'%20y='15'%20width='1.5'%20height='3.2'%20rx='0.75'%20fill='%23ffffff'/%3E%3C/svg%3E")
52	      13 5, pointer;
53	}
54	* { box-sizing: border-box; }
55	html { scroll-behavior: smooth; }
56	body {
57	  margin: 0;
58	  font-family: var(--sans);
59	  color: var(--ink);
60	  background: var(--bg);
61	  line-height: 1.5;
62	}
63	[hidden] { display: none !important; }
64	.container { width: 100%; max-width: var(--maxw); margin: 0 auto; padding-inline: 24px; }
65	a { color: inherit; }
66	.sr-only {
67	  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
68	  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
69	}
70	
71	/* ============ Header ============ */
72	.site-header {
73	  border-bottom: 1px solid var(--line);
74	  position: sticky; top: 0; z-index: 50;
75	  background: rgba(255, 255, 255, 0.95);
76	  backdrop-filter: blur(6px);
77	}
78	.header-inner { display: flex; align-items: center; height: 64px; gap: 24px; }
79	.logo {
80	  font-family: var(--display); font-weight: 700; font-size: 1.4rem;
81	  letter-spacing: -0.01em; text-decoration: none; white-space: nowrap;
82	}
83	.logo-now { color: var(--violet); }
84	.main-nav { display: flex; gap: 28px; margin-inline: auto; }
85	.nav-link {
86	  text-decoration: none; font-size: 0.98rem; padding-bottom: 2px;
87	  border-bottom: 2px solid transparent; color: var(--ink);
88	}
89	.nav-link:hover { color: var(--violet); }
90	.nav-link.is-active { color: var(--violet); border-bottom-color: var(--violet); }
91	.header-hint { font-size: 0.8rem; color: var(--muted); white-space: nowrap; }
92	/* One debug pill (version + a popover with testing tools + the live average
93	   reschedule time). A quiet neutral chip — no longer a loud red banner. */
94	.debug-menu { position: relative; }
95	.debug-pill {
