266	.more-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px 22px; padding: 8px 4px 14px; }
267	.more-field-label {
268	  display: block; text-transform: uppercase; letter-spacing: 0.05em;
269	  font-size: 0.68rem; font-weight: 700; color: var(--muted); margin: 0 0 7px;
