286	/* ============ Availability calendar ============ */
287	.cal-card { padding: 30px 28px 26px; }
288	.cal-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; flex-wrap: wrap; }
289	.cal-top-left { min-width: 0; max-width: 640px; }
290	.cal-title-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
291	.cal-title {
292	  font-family: var(--display); font-weight: 700; font-size: 1.5rem;
293	  letter-spacing: -0.01em; margin: 0 0 6px;
294	}
295	/* Collapse / expand the grid canvas. */
296	.cal-collapse {
297	  display: inline-flex; align-items: center; gap: 5px;
298	  font: inherit; font-size: 0.78rem; font-weight: 600; color: var(--muted);
299	  background: #fff; border: 1px solid var(--line); border-radius: 999px;
300	  padding: 4px 12px; cursor: pointer; margin-bottom: 6px;
