302	.cal-collapse:hover { color: var(--ink); border-color: #d5d9e2; }
303	.cal-collapse .cc-caret { transition: transform 0.18s ease; }
304	#screen2.is-collapsed .cal-collapse .cc-caret { transform: rotate(-90deg); }
305	#screen2.is-collapsed .cal-wrap,
306	#screen2.is-collapsed .cal-legend { display: none; }
307	
308	/* The favourites provenance line: what's loaded, plus quiet replace/clear
309	   actions — deliberately low-key, no button chrome, no accent colour. */
310	.fav-line {
311	  display: flex; align-items: baseline; gap: 4px 8px; flex-wrap: wrap;
312	  margin: 0; font-size: 0.85rem; color: var(--muted);
313	}
314	.fav-action {
315	  font: inherit; font-size: 0.82rem; color: var(--muted);
316	  background: none; border: none; padding: 0; cursor: pointer;
317	  text-decoration: underline; text-underline-offset: 2px;
318	  text-decoration-color: #c6cdda;
319	}
320	.fav-action:hover { color: var(--ink); text-decoration-color: currentColor; }
321	.fav-sep { color: #c6cdda; }
322	
323	/* The payoff number — scheduled / in-window / favourites */
324	.hero-count { text-align: right; flex: 0 0 auto; }
325	.hc-num {
326	  font-weight: 800; font-size: 2.7rem; line-height: 1; letter-spacing: -0.02em;
327	  color: var(--violet-dark); white-space: nowrap;
328	}
329	.hc-num #hcIn { color: var(--muted); }
330	.hc-num .hc-of { color: #b7bcc9; font-weight: 700; font-size: 1.7rem; }
331	.hc-num.bump { animation: countbump 0.4s ease; }
332	@keyframes countbump {
333	  0% { transform: scale(1); }
334	  45% { transform: scale(1.09); color: var(--violet); }
335	  100% { transform: scale(1); }
336	}
337	.hc-label { font-size: 0.84rem; font-weight: 600; color: var(--ink); margin-top: 2px; }
338	.hc-detail { font-size: 0.78rem; color: var(--muted); font-variant-numeric: tabular-nums; }
339	
340	/* The availability-status legend colours mirror edfringe.com's own day-picker
341	   legend (see plan.js segClass / the --fr-* tokens below). */
342	.opt-select {
343	  font: inherit; font-size: 0.84rem; font-weight: 600; color: var(--ink);
344	  border: 1px solid var(--line); border-radius: 10px; background: #fff;
345	  padding: 7px 10px; cursor: pointer;
346	}
347	.opt-select:focus-visible { outline: 3px solid var(--violet); outline-offset: 2px; }
348	.btn-sm { padding: 8px 14px; font-size: 0.84rem; border-radius: 10px; box-shadow: 0 4px 12px rgba(108, 76, 241, 0.22); }
349	.legend { display: flex; gap: 10px 16px; flex-wrap: wrap; }
350	.lg { display: inline-flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--muted); }
351	.lg i { width: 14px; height: 11px; border-radius: 3px; display: block; }
352	.lg-avail i   { background: var(--fr-avail); }
353	.lg-2for1 i   { background: var(--fr-2for1-weave); }
354	.lg-preview i { background: var(--fr-preview); }
355	.lg-free i    { background: var(--fr-free); }
356	.lg-event i   { background: var(--fr-event); }
357	.lg-noalloc i { background: var(--fr-noalloc); }
358	
359	/* --- The calendar canvas --- */
360	/* .cal-wrap is the scroll container: the sticky block (window-control rail +
361	   day header) stays at its top while the lane list scrolls beneath it. The
362	   toolbar/hero-count above are outside this container entirely, so they never
363	   scroll away either. */
364	.cal-wrap {
365	  position: relative; margin-top: 20px;
366	  /* Deliberately shallow: the calendar is now the "pick your window" step that
367	     feeds the planner below it, so it stays compact and scrolls internally
368	     rather than pushing the Plan card off-screen. */
369	  max-height: 38vh; overflow-y: auto; overflow-x: hidden;
370	  border-radius: 10px;
371	}
372	.cal-inner { position: relative; }
373	
374	.cal-sticky { position: sticky; top: 0; z-index: 4; background: var(--paper); }
375	
376	/* minmax(0, …) on the day track lets the 31 columns shrink to the available
377	   width instead of holding their content's min-width and forcing the whole grid
378	   (day header + lanes) to overflow — which clipped the "In plan" column and the
379	   window flags on a narrower page. */
380	.cal-row { display: grid; grid-template-columns: 184px minmax(0, 1fr) 104px; gap: 0 12px; align-items: center; }
381	
382	.cal-head { border-bottom: 1px solid var(--line); padding-bottom: 6px; }
383	.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
384	.days { display: grid; grid-template-columns: repeat(31, minmax(0, 1fr)); gap: 3px; }
385	.day-col { text-align: center; line-height: 1.15; }
386	.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
387	.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
388	.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
389	.day-col.pre .day-num, .day-col.pre .day-dow { color: #cfd4de; }
390	
391	.lanes { position: relative; z-index: 1; }
392	/* One tight single-line row per show — this screen is an overview of the shows
393	   you want, so each row is deliberately compact (title only, no meta line). */
394	.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
395	.lane:last-child { border-bottom: none; }
396	.lane-label { min-width: 0; display: flex; align-items: center; gap: 4px; }
397	.lane-title {
398	  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
399	  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
400	}
401	/* The must-see pin — hidden unless the row is forced into the plan. */
402	.lane-pin { flex: 0 0 auto; font-size: 0.72rem; display: none; }
403	.lane--forced .lane-pin { display: inline; }
404	/* Drop this show from the list. Pushed to the right of the label, faint until
405	   the row is hovered/focused so it stays out of the way on a dense grid. */
406	.lane-remove {
407	  flex: 0 0 auto; margin-left: auto;
408	  border: 0; background: none; padding: 0 2px; cursor: pointer;
409	  font-size: 0.95rem; line-height: 1; color: #c2c8d2;
410	  opacity: 0.35; transition: opacity 0.12s ease, color 0.12s ease;
411	}
412	.lane:hover .lane-remove, .lane-remove:focus-visible { opacity: 1; }
413	.lane-remove:hover { color: var(--warn); }
414	/* A scheduled row gets a faint green wash so the grid mirrors the plan (the
415	   Status column carries the ✓ In plan text; no coloured left bar). */
416	.lane--scheduled { background: rgba(5, 150, 105, 0.05); }
417	/* The name and the performance marks are the two click targets (lock the show /
418	   lock that performance). The padlock cursor carries that affordance. */
419	.lane-label { cursor: var(--lock-cursor); }
420	.lane-label:hover .lane-title { text-decoration: underline; }
421	.lane-track { display: grid; grid-template-columns: repeat(31, minmax(0, 1fr)); gap: 3px; align-items: center; height: 100%; }
422	
423	/* A day cell holds one coloured segment per performance; two performances on a
424	   day render as two side-by-side segments — the split IS the "two shows that
425	   day" cue. Single-performance days read as one solid bar. */
426	.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; cursor: var(--lock-cursor); }
427	.cell:hover { box-shadow: 0 0 0 2px rgba(16, 24, 40, 0.3); }
428	.cell-multi { gap: 1.5px; }
429	.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
430	/* The performance the plan actually *set* for this show — the grid mirrors the
431	   itinerary, turning the chosen day/time into a gold bar (the higher-specificity
432	   .seg.seg--selected wins over the availability colour), so a locked-in mark
433	   reads as a little gold bar rather than a green-ringed availability chip. */
434	.seg.seg--selected, .seg.seg--pinned { background: var(--fr-locked); }
435	.seg--selected, .seg--pinned { box-shadow: inset 0 0 0 1px #e0b23a, 0 1px 2px rgba(190, 145, 20, 0.4); }
436	/* A whole-show pin: every performance gets a dashed gold border (you've forced
437	   the show in; the scheduler still picks which one, and that one goes solid gold
438	   via .seg--selected). Outline — not box-shadow — so it can be dashed; the
439	   negative offset pulls it inside the mark so overflow:hidden doesn't clip it. */
440	.seg--forced-all { outline: 1.5px dashed #e0b23a; outline-offset: -1.5px; }
441	/* A pinned exact performance: the same gold bar, plus a lock badge that sits
442	   above the mark. The badge deliberately overlaps the row above, so the pinned
443	   cell drops its overflow clip to let it escape upward. */
444	.seg--pinned { position: relative; }
445	.cell--pin { overflow: visible; }
446	.seg-pin {
447	  position: absolute; left: 50%; bottom: 100%;
448	  transform: translate(-50%, 30%);
449	  font-size: 0.82rem; line-height: 1; pointer-events: none; z-index: 6;
450	  filter: drop-shadow(0 1px 1px rgba(16, 24, 40, 0.35));
451	}
452	.seg-avail   { background: var(--fr-avail); }
453	.seg-2for1   { background: var(--fr-2for1-weave); }
454	.seg-preview { background: var(--fr-preview); }
455	.seg-free    { background: var(--fr-free); }
456	.seg-event   { background: var(--fr-event); }
457	.seg-noalloc { background: var(--fr-noalloc); }
458	/* Sold out shares the red "no allocation" mark — both mean "no online ticket". */
459	.seg-sold    { background: var(--fr-noalloc); }
460	
461	/* Fixed-height row so the pushpin (a tall glyph) can't stretch a lane taller
462	   than its neighbours — there's no vertical room for that. Content is clamped
463	   and centred; the pin sits just left of the status pill. */
464	.lane-status {
465	  font-size: 0.72rem; line-height: 1.1; text-align: center;
466	  display: flex; align-items: center; justify-content: center; gap: 2px;
467	  height: 20px; overflow: hidden;
468	}
469	.lane-status .st-pin { font-size: 0.62rem; line-height: 1; flex: 0 0 auto; }
470	.lane-status .st-plan {
471	  font-weight: 700; color: var(--ok-text); white-space: nowrap;
472	  background: var(--ok-bg); border-radius: 999px; padding: 2px 7px;
473	}
474	.lane-status .st-in { color: var(--violet-dark); font-weight: 600; white-space: nowrap; }
475	.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
476	/* "Can't fit" — catchable but crowded out; muted, no alarm. */
477	.lane-status .st-cant { color: var(--muted); font-weight: 600; white-space: nowrap; }
478	/* "Sold out" — greyed, matching the sold-out day marks. */
479	.lane-status .st-sold { color: #98a2b3; font-weight: 700; white-space: nowrap; }
480	/* "Bad dates" — a dates problem the window scrubber fixes; quiet violet. */
481	.lane-status .st-dates { color: var(--violet-dark); font-weight: 600; white-space: nowrap; }
482	/* Every show that isn't in the plan reads the same, whatever the reason (out of
483	   window, can't fit, too early/late, sold out): one dimmed title. A scheduled or
484	   forced row is never dimmed — it made the plan. Out-of-window shows also recede
485	   their day marks, to the same transparency, since none fall in your dates;
486	   in-window shows keep their marks bright (those marks still mean something). */
487	.lane:not(.lane--scheduled) .lane-title { opacity: 0.42; }
