543	.win-handle {
544	  position: absolute; top: 0; bottom: 0; width: 26px;
545	  transform: translateX(-50%);
546	  cursor: grab; touch-action: none; z-index: 1;
547	}
548	.win-handle:active { cursor: grabbing; }
549	/* The tab's stem: a short violet line down to the day header, continuing
550	   visually into the band edge below the header. */
551	.win-handle::before {
552	  content: ""; position: absolute; left: 50%; top: 6px; bottom: 0;
553	  width: 2px; margin-left: -1px; background: var(--violet);
554	}
555	/* The draggable knob. A raised pill button with a grip on its outer edge, so it
556	   reads as grab-and-slide rather than a static date label. Tabs anchor OUTWARD
557	   from their stem (start points left, end points right) so they never collide
558	   even when the window is dragged narrow. The "0 2px 0" layer is a solid bottom
559	   edge that gives the button height; the press state below sinks it. */
560	/* A solid violet chip planted on the stem line — reads as a little flag/marker
561	   on the date, not a text label. A quiet "From"/"To" cap disambiguates the two
562	   ends; the inner-bottom corner squares off where the chip meets its stem so it
563	   looks planted. No more grip bars. */
564	.win-flag {
565	  position: absolute; top: 2px;
566	  display: inline-flex; align-items: baseline; gap: 5px;
567	  font-size: 0.74rem; font-weight: 800; color: #fff;
568	  background: linear-gradient(180deg, #7d5cf5, var(--violet));
569	  border-radius: 9px;
570	  padding: 5px 10px; white-space: nowrap;
571	  box-shadow: 0 4px 10px rgba(90, 63, 214, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.25);
572	  font-variant-numeric: tabular-nums;
573	  cursor: grab;
574	  transition: transform 0.1s ease, box-shadow 0.1s ease, background 0.12s ease;
575	}
576	.win-flag .wf-cap {
577	  font-size: 0.56rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0.72;
578	}
579	.win-handle--start .win-flag { right: 50%; margin-right: -1px; border-bottom-right-radius: 2px; }
580	.win-handle--end .win-flag { left: 50%; margin-left: -1px; border-bottom-left-radius: 2px; }
581	.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
582	  background: linear-gradient(180deg, #6c4cf1, var(--violet-dark));
583	  transform: translateY(-1px);
584	  box-shadow: 0 6px 14px rgba(90, 63, 214, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.25);
585	}
586	/* Pressed: settle the chip for a tactile grab. */
587	.win-handle:active .win-flag {
588	  transform: translateY(0); cursor: grabbing;
589	  box-shadow: 0 2px 6px rgba(90, 63, 214, 0.4);
590	}
591	.win-handle:focus-visible { outline: none; }
592	.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.4), 0 6px 14px rgba(16, 24, 40, 0.2); }
