596	.win { position: absolute; top: 0; bottom: 0; z-index: 2; pointer-events: none; }
597	.festend { position: absolute; top: 0; bottom: 0; background: rgba(234, 236, 240, 0.35); border-right: 1px dashed #d5d9e2; pointer-events: none; z-index: 1; }
598	.win-dim { position: absolute; top: 0; bottom: 0; background: rgba(247, 248, 250, 0.72); }
