601	  background: rgba(108, 76, 241, 0.05);
602	  border-left: 2px solid var(--violet); border-right: 2px solid var(--violet);
603	}
604	/* Draggable grips on the band's two vertical lines — a thin ew-resize strip
605	   centred on each edge. pointer-events re-enabled here (the overlay itself is
606	   inert), so the rest of the grid keeps its cell hovers. */
