716	/* --- The schedule graphic --- */
717	.schedule-wrap {
718	  overflow-x: auto; border: 1px solid var(--line); border-radius: 12px;
719	  background:
720	    linear-gradient(#fff, #fff) padding-box,
721	    repeating-linear-gradient(90deg, #fbfbfd 0 1px, transparent 1px 100%);
722	  padding: 0;
723	}
724	/* position:relative anchors the draggable day-hours / meal overlay. */
725	.schedule { display: flex; align-items: stretch; min-width: min-content; width: 100%; position: relative; }
726	/* Left time gutter: a head spacer (matching the day headers) then a body whose
727	   hour labels line up with the day columns' gridlines. */
728	.sch-gutter { flex: 0 0 52px; display: flex; flex-direction: column; border-right: 1px solid var(--line); }
729	.sch-gutter-head { height: var(--sch-head-h, 46px); border-bottom: 1px solid var(--line); }
730	.sch-gutter-body { position: relative; flex: 1 0 auto; }
731	.sch-hour {
732	  position: absolute; right: 8px; font-size: 0.68rem; font-weight: 600;
733	  color: #b0b7c3; font-variant-numeric: tabular-nums; transform: translateY(-50%);
734	}
735	/* Day columns flex to share the available width so every scheduled day fits on
736	   screen; they only fall back to horizontal scroll below the min-width floor.
737	   The floor is deliberately tight (44px) so even a long multi-week window fits
738	   the page width before scrolling — a packed plan reads better as narrow columns
739	   than as an off-screen header. */
740	.sch-day {
741	  flex: 1 1 0; min-width: 44px; border-right: 1px solid var(--line);
742	  display: flex; flex-direction: column;
743	}
744	.sch-day:last-child { border-right: none; }
745	.sch-day-head {
746	  height: var(--sch-head-h, 46px); box-sizing: border-box;
747	  display: flex; flex-direction: column; justify-content: center;
748	  padding: 6px 8px; border-bottom: 1px solid var(--line);
749	  position: sticky; top: 0; background: var(--paper); z-index: 1;
750	  overflow: hidden;
751	}
752	.sch-day.wknd .sch-day-head { background: #fbfaff; }
753	.sch-dow { font-size: 0.7rem; font-weight: 700; color: var(--ink); line-height: 1.15; }
754	/* At a narrow column the date drops under the weekday rather than overflowing. */
755	.sch-dow .sch-date { display: inline-block; color: var(--muted); font-weight: 600; }
756	.sch-day-count { font-size: 0.66rem; color: var(--muted); }
757	/* The day's time canvas: hour gridlines via a repeating gradient, shows
758	   positioned absolutely against the shared axis. */
759	.sch-body {
760	  position: relative; flex: 1 0 auto;
761	  background-image: repeating-linear-gradient(
762	    to bottom, transparent 0 calc(var(--sch-hour-h) - 1px), var(--line) calc(var(--sch-hour-h) - 1px) var(--sch-hour-h)
763	  );
764	  background-position: 0 0;
765	}
766	.sch-show {
767	  position: absolute; left: 3px; right: 3px; overflow: hidden;
768	  border-radius: 7px; padding: 2px 5px;
769	  background: #fff; border: 1px solid var(--line);
770	  border-left: 4px solid var(--seg, var(--violet));
771	  box-shadow: 0 2px 6px rgba(16, 24, 40, 0.07);
772	  font-size: 0.72rem; line-height: 1.2;
773	  display: flex; gap: 4px; align-items: flex-start; cursor: var(--lock-cursor);
774	  text-decoration: none; color: var(--ink); /* it's an <a> — strip link chrome */
775	}
776	.sch-show:hover { box-shadow: 0 4px 12px rgba(16, 24, 40, 0.16); border-color: #d5d9e2; z-index: 3; }
777	.sch-show:focus-visible { outline: 3px solid var(--violet); outline-offset: 1px; z-index: 3; }
778	/* A locked-in (forced) show wears a green ring + a lock badge, so the schedule
779	   shows *why* the plan looks the way it does — a pinned show is the only kind
780	   that can land inside a meal break or outside your day hours. The badge is a
781	   filled chip in the top-right corner so it reads on a small block too. */
782	.sch-show--pinned { border-color: var(--ok); box-shadow: inset 0 0 0 1.5px var(--ok), 0 2px 6px rgba(16, 24, 40, 0.1); }
783	.sch-show--pinned:hover { box-shadow: inset 0 0 0 1.5px var(--ok), 0 4px 12px rgba(16, 24, 40, 0.16); }
784	.sch-pin {
785	  position: absolute; top: 1px; right: 1px; z-index: 3; pointer-events: none;
786	  width: 16px; height: 16px; display: grid; place-items: center;
787	  font-size: 0.64rem; line-height: 1;
788	  background: #fff; border: 1.5px solid var(--ok); border-radius: 50%;
789	  box-shadow: 0 1px 3px rgba(16, 24, 40, 0.3);
790	}
791	/* Genre emoji, pinned to the left edge. */
792	.sch-emoji { flex: 0 0 auto; font-size: 0.92rem; line-height: 1.1; }
793	.sch-body-text { min-width: 0; flex: 1; }
794	/* The start–end time is deliberately tiny + faint — the name is what matters. */
795	.sch-time {
796	  display: block; font-weight: 600; color: var(--muted); opacity: 0.7;
797	  font-variant-numeric: tabular-nums; font-size: 0.56rem; letter-spacing: 0.01em;
798	}
799	/* The title carries the block. Regular weight (not bold) reads calmer and fits
800	   more of the name before the 2-line clamp bites. */
801	.sch-name {
802	  font-family: var(--display); font-weight: 500; color: var(--ink); font-size: 0.72rem;
803	  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
804	}
805	.sch-venue { color: var(--muted); font-size: 0.64rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
806	/* Tight columns shed chrome so the title keeps the room: narrow drops the time,
807	   tiny drops the genre emoji and trims padding to the bone. */
808	.schedule.cols-narrow .sch-show { padding: 2px 4px; }
809	.schedule.cols-narrow .sch-time { display: none; }
810	.schedule.cols-narrow .sch-venue { display: none; }
811	.schedule.cols-tiny .sch-show { left: 2px; right: 2px; gap: 2px; border-left-width: 3px; }
812	.schedule.cols-tiny .sch-emoji { display: none; }
813	/* Left-accent colours reuse the edfringe.com availability palette. The 2-for-1
814	   accent is a single 4px rule, too thin for the diagonal weave, so it takes the
815	   teal "available" half of that pairing. */
