817	.seg-2for1   { --seg: var(--fr-avail); }
818	.seg-preview { --seg: var(--fr-preview); }
819	.seg-free    { --seg: var(--fr-free); }
820	.seg-event   { --seg: var(--fr-event); }
821	.seg-noalloc { --seg: var(--fr-noalloc); }
822	
823	.schedule-empty { margin: 0; padding: 28px 20px; text-align: center; color: var(--muted); font-size: 0.9rem; }
