825	/* --- Travel legs: a narrow block in the gap between shows < 1h apart --- */
826	.sch-leg {
827	  position: absolute; left: 22px; right: 22px; overflow: hidden;
828	  display: flex; align-items: center; justify-content: center; gap: 4px;
829	  border-radius: 6px; padding: 0 4px;
