export function showPrice(show) {
  if (!show) return null;
  const raw = show.price;
  if (typeof raw === "number" && Number.isFinite(raw)) return raw;
  if (typeof raw === "string") {
    const m = /(\d+(?:\.\d+)?)/.exec(raw);
    if (m) return Number(m[1]);
  }
  if (show.free) return 0;
  return null;
}

