test("matching folds case and accents", () => {
  const cafe = show({ slug: "c", title: "Café Chansons" });
  assert.equal(searchShows([cafe], "CAFE", {}).results.length, 1);
  assert.equal(searchShows([cafe], "café", {}).results.length, 1);
