test("filters and query compose; limit caps results but total counts all", () => {
  const shows = [];
  for (let i = 0; i < 40; i++) {
    shows.push(show({ slug: `s${i}`, title: `Magic ${String(i).padStart(2, "0")}`, genre: i % 2 ? "Comedy" : "Theatre" }));
