// Drives the planner's new show search end to end and screenshots each state.
// Usage: node drive-search.mjs <outDir> [baseUrl]
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";
import { mkdirSync } from "node:fs";

const OUT = process.argv[2] || "./shots";
const BASE = process.argv[3] || "http://localhost:8000";
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1360, height: 940 } });

const errors = [];
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
page.on("pageerror", (e) => errors.push(String(e)));

const shot = (name, opts = {}) => page.screenshot({ path: `${OUT}/${name}.png`, ...opts });
const check = (cond, msg) => { if (!cond) { console.error("FAIL: " + msg); process.exitCode = 1; } else console.log("ok: " + msg); };

await page.goto(BASE + "/plan/", { waitUntil: "networkidle" });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: "networkidle" });
await page.waitForFunction(() => document.getElementById("ssInput").placeholder.includes("shows"));
await shot("1-intake", { fullPage: true });

// --- search from the empty state -------------------------------------------
await page.fill("#ssInput", "magic");
await page.waitForSelector("#ssPop:not([hidden])");
await page.waitForTimeout(250);
const rowCount = await page.locator("#ssResults .ss-row").count();
check(rowCount > 0, `results for "magic" (${rowCount} rows)`);
check(await page.locator("#ssResults .ss-row .ss-star").first().textContent() === "☆", "first star starts empty");
await shot("2-intake-search");

// --- star the first result → the calendar takes over ------------------------
const firstTitle = (await page.locator("#ssResults .ss-row .ss-row-title").first().textContent()).trim();
await page.locator("#ssResults .ss-row").first().click();
await page.waitForSelector("#screen2:not([hidden])");
await page.waitForTimeout(500);
check(await page.locator("#ssSlotCal #showSearch").count() === 1, "search bar moved to the grid slot");
check(!(await page.locator("#ssPop").getAttribute("hidden") !== null) || (await page.locator("#ssPop:not([hidden])").count()) === 1, "popup still open after the flip");
check((await page.locator("#ssResults .ss-row.is-on .ss-star").first().textContent()) === "★", "added row's star is filled");
check((await page.locator("#lanes .lane").count()) === 1, "one lane on the grid");
const laneTitle = (await page.locator("#lanes .lane-title").first().textContent()).trim();
check(laneTitle === firstTitle, `lane title matches starred show (${laneTitle})`);
await shot("3-grid-after-add", { fullPage: true });

// --- add a second show from the grid state ----------------------------------
await page.locator("#ssResults .ss-row:not(.is-on)").first().click();
await page.waitForTimeout(500);
check((await page.locator("#lanes .lane").count()) === 2, "two lanes after second star");

// --- drag the date window, add a third, check the window survives ------------
await page.evaluate(() => window.scrollTo(0, 0));
const flagBefore = await page.locator("#flagStart").textContent();
await page.locator("#hStart").focus();
await page.keyboard.press("ArrowRight");
await page.keyboard.press("ArrowRight");
await page.waitForTimeout(300);
const flagMoved = await page.locator("#flagStart").textContent();
check(flagMoved !== flagBefore, `window start nudged (${flagBefore} → ${flagMoved})`);
await page.locator("#ssInput").click();
await page.waitForTimeout(250);
await page.locator("#ssResults .ss-row:not(.is-on)").first().click();
await page.waitForTimeout(500);
check((await page.locator("#flagStart").textContent()) === flagMoved, "date window survives a one-by-one add");
check((await page.locator("#lanes .lane").count()) === 3, "three lanes");

// --- search tools line -------------------------------------------------------
await page.click("#ssToolsBtn");
await page.waitForSelector("#ssTools:not([hidden])");
check(await page.locator("#ssfAccess").isDisabled(), "accessibility select disabled (no data yet)");
check(await page.locator('#ssfPrice option[value="15"]').isDisabled(), "price caps disabled (no data yet)");
check(!(await page.locator('#ssfPrice option[value="free"]').isDisabled()), "price 'Free' stays enabled");
await page.selectOption("#ssfGenre", "Comedy");
await page.waitForTimeout(300);
const badge = await page.locator("#ssBadge").textContent();
check(badge === "1", `filter badge shows 1 (got ${badge})`);
const metas = await page.locator("#ssResults .ss-row-meta").allTextContents();
check(metas.length > 0 && metas.every((m) => m.includes("Comedy")), "filtered results are all Comedy");
await shot("4-tools-filtered", { fullPage: true });

// --- free filter works off the free flag today -------------------------------
await page.selectOption("#ssfPrice", "free");
await page.fill("#ssInput", "");
await page.waitForTimeout(300);
const freeMetas = await page.locator("#ssResults .ss-row-meta").allTextContents();
check(freeMetas.length > 0 && freeMetas.every((m) => m.startsWith("Free")), "free+Comedy browse: every row marked Free");
await shot("5-free-browse");

// --- reset filters, remove a show via its gold star --------------------------
await page.click("#ssReset");
await page.waitForTimeout(200);
check(await page.locator("#ssBadge").isHidden(), "badge cleared on reset");
await page.fill("#ssInput", "magic");
await page.waitForTimeout(300);
await page.locator("#ssResults .ss-row.is-on").first().click();
await page.waitForTimeout(500);
check((await page.locator("#lanes .lane").count()) === 2, "star toggle removed a show (back to two lanes)");
await shot("6-after-remove", { fullPage: true });

// --- keyboard: arrow down + enter adds the highlighted row -------------------
await page.locator("#ssInput").click();
await page.keyboard.press("ArrowDown");
await page.keyboard.press("Enter");
await page.waitForTimeout(500);
check((await page.locator("#lanes .lane").count()) === 3, "keyboard enter re-added a show");

// --- escape + click-away close the popup ------------------------------------
await page.keyboard.press("Escape");
check((await page.locator("#ssPop:not([hidden])").count()) === 0, "escape closes the popup");

const realErrors = errors.filter((e) => !e.includes("favicon.ico") && !e.includes("ERR_CONNECTION_RESET"));
check(realErrors.length === 0, `no console errors (${JSON.stringify(realErrors).slice(0, 300)})`);

await browser.close();
console.log(process.exitCode ? "VISUAL PASS FAILED" : "VISUAL PASS OK");

